import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { getCategoryById, getCategoryPath, Category } from './data/categories';
import { getPostById } from './services/postService';

interface BreadcrumbProps {
  path: string[];
  onClick: (index: number) => void;
}

const Breadcrumb: React.FC<BreadcrumbProps> = ({ path, onClick }) => {
  const location = useLocation();

  // Check if we're viewing a post
  const isViewingPost = location.pathname.includes('/post/');
  let postTitle = '';
  let categoryPath: Category[] = [];

  if (isViewingPost) {
    const postIdMatch = location.pathname.match(/\/post\/([^/]+)/);
    if (postIdMatch && postIdMatch[1]) {
      const post = getPostById(postIdMatch[1]);
      if (post) {
        postTitle = post.title;

        // If this is a post with a compound category ID like "art-painting"
        // Use the full ID to get the proper category path
        if (post.categoryId.includes('-')) {
          // Get the full path to the leaf category
          categoryPath = getCategoryPath(post.categoryId);
        } else {
          // Simple case: just a single category
          const category = getCategoryById(post.categoryId);
          if (category) {
            categoryPath = [category];
          }
        }
      }
    }
  } else if (path.length > 0) {
    // For normal category navigation, use the last category ID to get the full path
    const lastCategoryId = path[path.length - 1];
    if (lastCategoryId && lastCategoryId.includes('-')) {
      // This is a compound category ID
      categoryPath = getCategoryPath(lastCategoryId);
    } else {
      // Just use the path as is
      categoryPath = path.map(id => getCategoryById(id)).filter(Boolean) as Category[];
    }
  }

  return (
	<div className="breadcrumb">
	  {/* Show breadcrumb based on properly resolved category path */}
	  {categoryPath.length > 0 && categoryPath.map((category, index) => (
		<span key={category.id}>
		  <Link to={`/category/${category.id}`} onClick={() => onClick(index)}>
			{category.name}
		  </Link>
		  {index < categoryPath.length - 1 && ' > '}
		</span>
	  ))}

	  {/* Add post title to breadcrumb if viewing a post */}
	  {isViewingPost && postTitle && (
		<span>
		  {categoryPath.length > 0 && ' > '}
		  <span className="current">{postTitle}</span>
		</span>
	  )}
	</div>
  );
};

export default Breadcrumb;
